-- FINAGRO Web — hostile operational finance integration tests.
begin;
create schema test_finance;
create function test_finance.ok(v boolean,m text) returns void language plpgsql set search_path='' as $$begin if v is not true then raise exception 'TEST FAILED: %',m;end if;end$$;
create function test_finance.fails(sql text,fragment text) returns void language plpgsql set search_path='' as $$declare m text;begin begin execute sql;set constraints all immediate;exception when others then m=sqlerrm;set constraints all deferred;if position(fragment in m)=0 then raise exception 'TEST FAILED: expected %, got %',fragment,m;end if;return;end;raise exception 'TEST FAILED: expected error %',fragment;end$$;
grant usage on schema test_finance to authenticated;grant execute on all functions in schema test_finance to authenticated;
