select public.save_financial_entry('91000000-0000-0000-0000-000000000010',null,'SAIDA','AGENDADO','2026-01-02','2026-02-02',null,null,'Rateio centavos',null,'91000000-0000-0000-0000-000000000401','91000000-0000-0000-0000-000000000301',null,null,100000.01,null,'RATEIO',null,'91000000-0000-0000-0000-000000000701');
select test_finance.ok((select count(*)=2 from public.financial_entries),'one entry per operation, not one per allocation');select test_finance.ok((select count(*)=1 and sum(percentage)=100 and sum(allocated_amount)=100 from public.entry_allocations a join public.financial_entries e on e.id=a.financial_entry_id where e.description='Entrada direta'),'direct allocation 100 percent');select test_finance.ok((select count(*)=3 and sum(allocated_amount)=100000.01 from public.entry_allocations a join public.financial_entries e on e.id=a.financial_entry_id where e.description='Rateio centavos'),'rateio exact total with cent rounding');select test_finance.ok((select array_agg(allocated_amount order by percentage desc)=array[45000.00,40000.00,15000.01]::numeric[] from public.entry_allocations a join public.financial_entries e on e.id=a.financial_entry_id where e.description='Rateio centavos'),'45/40/15 expected allocation with residual on last deterministic farm');
update public.allocation_rule_items set percentage=44 where allocation_rule_id='91000000-0000-0000-0000-000000000701' and farm_id='91000000-0000-0000-0000-000000000101';update public.allocation_rule_items set percentage=41 where allocation_rule_id='91000000-0000-0000-0000-000000000701' and farm_id='91000000-0000-0000-0000-000000000102';set constraints all immediate;set constraints all deferred;select test_finance.ok((select array_agg(percentage order by percentage desc)=array[45,40,15]::numeric[] from public.entry_allocations a join public.financial_entries e on e.id=a.financial_entry_id where e.description='Rateio centavos'),'rule change preserves snapshot');
